using System;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace BWVR.Editor {
public static class ConstructionYardChecks {
 static void Require(bool valid,string reason){if(!valid)throw new Exception(reason);}
 [MenuItem("BWVR/Verify shared construction yard (Play mode)")]
 public static void Verify(){
  var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();Require(EditorApplication.isPlaying&&slice!=null,"Enter Play mode first");var sites=slice.GetComponentsInChildren<ConstructionSite>();Require(sites.Count(s=>!s.IsBridge)==1,"Multiple toy platforms remain");var site=sites.Single(s=>!s.IsBridge);Require(site.blocks.Count==48&&site.blocks.Select(b=>b.Shape).Distinct().Count()==8,"Missing piece types or stock");Require(site.HalfSize==new Vector2(30,24),"Shared platform was not enlarged");Require(slice.GetComponentInChildren<IslandDiscoveries>().points.All(p=>p.construction==null),"Remote discovery tray remains");
  var stateField=typeof(QuestSlice).GetField("state",BindingFlags.NonPublic|BindingFlags.Instance);var original=(SliceState)stateField.GetValue(slice);var saved=site.Capture();bool paused=site.Paused;var test=new SliceState{developmentFocus=true};var god=slice.GetComponentInChildren<CreatureHybrid>();var mind=god.GetComponent<CreatureCuriosity>();var routine=god.GetComponent<CreatureRoutine>();var nav=god.GetComponent<IslandNavigator>();var position=god.transform.position;var recipe=site.Recipe;god.Interrupt("Shared yard QA");foreach(var actor in slice.GetComponentsInChildren<VillagerExploration>())actor.ResetTask();foreach(var actor in slice.GetComponentsInChildren<VillagerBlockPlay>())actor.ResetTask();stateField.SetValue(slice,test);
  try{
   site.Paused=false;site.ResetConstruction();site.Recipe=BuildRecipe.Arch;
   var pads=new[]{new Vector3(-10,0,-12),new Vector3(0,0,-12),new Vector3(10,0,-12),new Vector3(-10,0,0),new Vector3(10,0,0),new Vector3(-10,0,12),new Vector3(0,0,12),new Vector3(10,0,12)};
   for(int i=0;i<8;i++){var block=site.blocks.First(b=>(int)b.Shape==i);Require(site.Drop(block,site.World(pads[i]+Vector3.up*block.size.y*.5f),site.transform.rotation,true),"Could not snap "+block.Shape);for(int n=0;n<5;n++)site.Advance(.02f);}
   var column=site.blocks.First(b=>b.Shape==ConstructionShape.Column);var upper=site.blocks.First(b=>b.Shape==ConstructionShape.Brick&&!b.Attached);Require(site.Drop(upper,site.World(column.Body.position+Vector3.up*(column.size.y+upper.size.y)*.5f),site.transform.rotation),"Mixed-height column stack failed");
   var before=site.blocks.Where(b=>b.Attached).ToDictionary(b=>b,b=>b.Body.position);for(int n=0;n<250;n++)site.Advance(.02f);Require(before.All(p=>p.Key.Attached&&Vector3.Distance(p.Key.Body.position,p.Value)<.03f),"Mixed assembly unstable");
   var physics=(PhysicsScene)typeof(ConstructionSite).GetField("physics",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(site);Require(!physics.Raycast(new Vector3(0,1.2f,10),Vector3.forward,out _,3),"Arch opening blocked by a box collider");Require(physics.Raycast(new Vector3(0,3,10),Vector3.forward,out _,3),"Arch lintel has no collision");Require(physics.Raycast(new Vector3(-9,6,12),Vector3.down,out var high,6)&&physics.Raycast(new Vector3(-11,6,12),Vector3.down,out var low,6)&&high.point.y-low.point.y>1,"Ramp collision is not sloped");
   var snapshot=site.Capture();Require(snapshot.Length==48&&ConstructionSite.Valid(snapshot),"48-piece save invalid");site.Restore(JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(new SliceState{construction=snapshot})).construction);Require(site.Snapped==9,"Assembly did not restore");snapshot[0].support=0;Require(!ConstructionSite.Valid(snapshot),"Cyclic support accepted");
   site.ResetConstruction();var legacy=site.Capture().Take(8).ToArray();legacy[0]=new ConstructionRecord{position=new Vector3(-2,.6f,0),rotation=Quaternion.identity,support=-1,creatureBuilt=true};legacy[1]=new ConstructionRecord{position=new Vector3(-2,1.8f,0),rotation=Quaternion.identity,support=0,creatureBuilt=true};site.Restore(legacy);Require(site.blocks[1].Connection.connectedBody==site.blocks[0].Body,"Legacy main assembly lost");site.ImportLegacyCache(0,legacy);site.ImportLegacyCache(1,legacy);Require(site.Snapped==6&&site.blocks[9].Connection.connectedBody==site.blocks[8].Body&&site.blocks[17].Connection.connectedBody==site.blocks[16].Body,"Old cache support references were not remapped");Require(Vector3.Distance(site.blocks[8].Body.position,legacy[0].position+new Vector3(-10,0,10))<.01f,"Cache did not move to shared yard");
   foreach(ConstructionShape shape in Enum.GetValues(typeof(ConstructionShape))){site.ResetConstruction();site.Recipe=shape==ConstructionShape.Beam?BuildRecipe.Bench:BuildRecipe.Arch;test.Building.observed=15;if(shape==ConstructionShape.Beam){for(int k=0;k<2;k++){var pier=site.blocks[k];Require(site.Drop(pier,site.World(new Vector3(k==0?-2:2,.6f,0)),site.transform.rotation),"Beam fixture supports failed");for(int n=0;n<5;n++)site.Advance(.02f);}}var block=site.blocks.First(b=>b.Shape==shape);mind.ResetTask();routine.ResetTask();if(!nav.world.Sample(block.transform.position,nav.profile,15,out var at))throw new Exception("No pickup access for "+shape);god.transform.position=nav.world.ProjectFoot(at,nav.profile);nav.ResetRoute();var affordance=block.GetComponent<CreatureAffordance>();affordance.cooldown=0;int built=mind.built;Require(mind.TryBegin(affordance),"Creature refused "+shape);for(int n=0;n<1000&&mind.Current!=CreatureCuriosity.Phase.Rest;n++){mind.Tick(.1f,test);site.Advance(.02f);}Require(block.Attached&&block.creatureBuilt&&!block.Item.held&&mind.built==built+1,"Creature could not carry/place "+shape+" phase="+mind.Current);}
   Debug.Log("BWVR_YARD_PASS: one 60x48 platform, 48 blocks/eight shapes; mixed-height physical snaps and stability; real arch opening and ramp slope; 48-piece save/cycle validation; old main/two caches remapped; native creature pickup/carry/place of every shape");
  }finally{god.Interrupt("Shared yard QA complete");mind.ResetTask();routine.ResetTask();god.transform.position=position;nav.ResetRoute();stateField.SetValue(slice,original);site.Recipe=recipe;site.Restore(saved);site.Paused=paused;}
 }
}
}
